37	  Future<void> _importFile() async {
38	    // 这里**故意不带 acceptedTypeGroups**。
39	    //
40	    // 原来写的是 XTypeGroup(label:'GPX', extensions:['gpx','xml'])，在 Android 上
41	    // 反而把 GPX 全部锁死：`file_selector_android` 用系统 MimeTypeMap 把扩展名翻
42	    // 成 MIME（FileSelectorApiImpl.tryConvertExtensionsToMimetypes），`gpx` 没有
43	    // 注册项 → 返回 null → 被丢弃，只剩 `xml` → `text/xml`。于是 allMimetypes
44	    // 只剩一项，走 `intent.setType("text/xml")` 这条分支，选择器只认 text/xml；
45	    // 而系统里 GPX 登记的 MIME 是 application/gpx+xml 或 application/octet-stream，
46	    // 于是文件变灰、点不动 —— 这就是"选不了 GPX"的原因。
47	    //
48	    // 不过滤 + 选完自己校验（GpxUtil.looksLikeGpx），行为可预期且跨机型一致。
49	    // 同一做法在 companion_fs_browser.dart 的上传入口一直是对的（它本来就没过滤）。
50	    final file = await openFile();
51	    if (file == null) return;
52	
53	    final bytes = await file.readAsBytes();
54	    final name = file.name.isEmpty ? 'import.gpx' : file.name;
55	
56	    if (!GpxUtil.looksLikeGpx(bytes)) {
57	      AppTheme.snack(LocaleKeys.gpxImportFile.tr, LocaleKeys.gpxNotGpx.tr);
58	      return;
59	    }
60	
61	    await _store.putBytes(name, bytes);
62	    await _reload();
63	  }
