58	  Future<RideRecord> putBytes(String fileName, List<int> bytes) async {
59	    await _ensureDir();
60	    final safe = GpxUtil.safeFileName(fileName);
61	    final file = File(p.join(_dir!.path, safe));
62	    final xml = GpxUtil.ensureTimestamps(utf8.decode(bytes, allowMalformed: true));
63	    final out = utf8.encode(xml);
64	    await file.writeAsBytes(out, flush: true);
65	    final sum = GpxUtil.parse(xml);
66	    final when = sum.endTime ?? DateTime.now().toUtc();
67	    final rec = RideRecord(
68	      fileName: safe,
69	      localPath: file.path,
70	      size: out.length,
71	      mtime: GpxUtil.unixSeconds(when),
72	      distanceKm: sum.distanceKm,
73	      pointCount: sum.points.length,
74	      durationSec: sum.duration?.inSeconds ?? 0,
75	      preview: GpxUtil.previewTrack(sum.points),
76	      displayName: sum.name.isEmpty ? null : sum.name,
77	    );
78	    _items.removeWhere((e) => e.fileName == safe);
79	    _items.insert(0, rec);
80	    await _flush();
