292	  /// 给还没有时长 / 缩略轨迹的记录补 GPX 数据。
293	  Future<bool> ensureDurations() async {
294	    var changed = false;
295	    for (var i = 0; i < _items.length; i++) {
296	      final rec = _items[i];
297	      if (rec.durationSec != null && rec.preview != null) continue;
298	      var sec = rec.durationSec ?? 0;
299	      var preview = rec.preview;
300	      final f = File(rec.localPath);
301	      if (await f.exists()) {
302	        try {
303	          final xml = utf8.decode(await f.readAsBytes(), allowMalformed: true);
304	          final sum = GpxUtil.parse(xml);
305	          if (rec.durationSec == null) {
306	            sec = sum.duration?.inSeconds ?? 0;
307	          }
308	          preview ??= GpxUtil.previewTrack(sum.points);
309	        } catch (_) {
310	          preview ??= const [];
311	        }
312	      } else {
313	        preview ??= const [];
314	      }
315	      _items[i] = rec.copyWith(durationSec: sec, preview: preview);
316	      changed = true;
317	    }
318	    if (changed) await _flush();
319	    return changed;
320	  }
321	}
322	
323	List<LatLng>? _previewFromJson(Object? raw) {
324	  if (raw is! List) return null;
325	  final out = <LatLng>[];
326	  for (final e in raw) {
327	    if (e is List && e.length >= 2) {
328	      final lat = (e[0] as num?)?.toDouble();
329	      final lon = (e[1] as num?)?.toDouble();
330	      if (lat != null && lon != null) out.add(LatLng(lat, lon));
331	    }
332	  }
333	  return out;
334	}
