167	  /// 把一份或多份 GPX 推上码表，进度只走全局悬浮框。
168	  ///
169	  /// 这里以前是 `useRootNavigator` 的模态对话框（还 `PopScope(canPop: false)`
170	  /// 锁住返回），退出页面就看不到进度了。改成登记到 [TransferCenter]：
171	  /// 悬浮框在路由之外，切页/返回都还在。
172	  static Future<T> _runWithProgress<T>({
173	    required String label,
174	    required Future<T> Function(_UploadTick onProgress) work,
175	  }) async {
176	    final center = TransferCenter.to;
177	    final task = center.begin(title: label, kind: _kind);
178	
179	    var lastUi = DateTime.fromMillisecondsSinceEpoch(0);
180	    // 多文件时每个文件的 done 都从 0 重新开始，直接当 transferred 会让
181	    // 测速窗口看到字节倒扣。用 base 把已完成文件的字节累积起来。
182	    var prevDone = 0;
183	    var base = 0;
184	
185	    try {
186	      final r = await work((done, total, {String? label}) {
187	        if (done < prevDone) {
188	          base += prevDone;
189	        }
190	        prevDone = done;
191	
192	        final now = DateTime.now();
193	        if (done < total &&
194	            now.difference(lastUi) < const Duration(milliseconds: 120) &&
195	            label == null) {
196	          return;
197	        }
198	        lastUi = now;
199	        center.progress(
200	          task,
201	          done: done,
202	          total: total,
203	          transferred: base + done,
204	          phase: label ?? task.phase,
205	        );
206	      });
207	      center.finish(task);
208	      return r;
209	    } catch (e) {
210	      center.fail(task, e);
211	      rethrow;
212	    }
213	  }
214	}
