186	  /// 用本机常用点覆盖码表 `/mnt/kv/bicycle_favorites.tsv`。
187	  static Future<int> pushFavorites(
188	    CompanionClient client, {
189	    void Function(McuSyncProgress p)? onProgress,
190	    int transferred = 0,
191	  }) async {
192	    _ensureReady(client);
193	    final store = FavoriteStore();
194	    await store.load();
195	    final pts = [
196	      for (final p in store.items.take(WaypointTsv.maxPts))
197	        (name: p.name, point: p.point),
198	    ];
199	    var tsv = WaypointTsv.encode(pts);
200	    if (tsv.isEmpty) {
201	      tsv = '\n';
202	    }
203	    final raw = utf8.encode(tsv);
204	    onProgress?.call(
205	      McuSyncProgress(
206	        phase: McuSyncPhase.pushFav,
207	        done: 0,
208	        total: raw.length,
209	        transferred: transferred,
210	      ),
211	    );
212	    await client.fsUpload(
213	      McuFsPaths.favoritesPath,
214	      raw,
215	      resume: false,
216	      onProgress: (d, t) {
217	        onProgress?.call(
218	          McuSyncProgress(
219	            phase: McuSyncPhase.pushFav,
220	            done: d,
221	            total: t,
222	            transferred: transferred + d,
223	          ),
224	        );
225	      },
226	    );
227	    return pts.length;
228	  }
