230	  /// 用本机坐标点记录覆盖码表 `mtp/navpts/*.tsv`。
231	  static Future<int> pushNavRoutes(
232	    CompanionClient client, {
233	    void Function(McuSyncProgress p)? onProgress,
234	    int transferred = 0,
235	  }) async {
236	    _ensureReady(client);
237	    try {
238	      await client.fsMkdir('mtp');
239	    } catch (_) {}
240	    try {
241	      await client.fsMkdir(McuFsPaths.navptsDir);
242	    } catch (_) {}
243	
244	    final store = NavRouteStore();
245	    await store.load();
246	    final jobs = <({String name, List<int> bytes})>[];
247	    final keep = <String>{};
248	    for (final rec in store.items) {
249	      if (rec.points.isEmpty) continue;
250	      var fileName = GpxUtil.safeTsvFileName(rec.name);
251	      var i = 2;
252	      while (keep.contains(fileName)) {
253	        fileName = GpxUtil.safeTsvFileName('${rec.name}_$i');
254	        i++;
255	      }
256	      keep.add(fileName);
257	      final pts = [
258	        for (var k = 0; k < rec.stops.length && k < WaypointTsv.maxPts; k++)
259	          (
260	            name: rec.stops[k].name.trim().isEmpty
261	                ? '${k + 1}'
262	                : rec.stops[k].name,
263	            point: rec.stops[k].point,
264	          ),
265	      ];
266	      jobs.add((name: fileName, bytes: utf8.encode(WaypointTsv.encode(pts))));
267	      if (jobs.length >= 32) break;
268	    }
269	
270	    final totalBytes = jobs.fold<int>(0, (s, j) => s + j.bytes.length);
271	    var doneBytes = 0;
272	    onProgress?.call(
273	      McuSyncProgress(
274	        phase: McuSyncPhase.pushNav,
275	        done: 0,
276	        total: totalBytes,
277	        transferred: transferred,
278	      ),
279	    );
280	    for (final j in jobs) {
281	      await client.fsUpload(
282	        CompanionFs.joinRel(McuFsPaths.navptsDir, j.name),
283	        j.bytes,
284	        resume: false,
285	        onProgress: (d, _) {
286	          onProgress?.call(
287	            McuSyncProgress(
288	              phase: McuSyncPhase.pushNav,
289	              done: doneBytes + d,
290	              total: totalBytes,
291	              transferred: transferred + doneBytes + d,
292	            ),
293	          );
294	        },
295	      );
296	      doneBytes += j.bytes.length;
297	    }
298	
299	    List<CompanionFsEntry> listed;
300	    try {
301	      listed = await client.fsList(McuFsPaths.navptsDir);
302	    } catch (_) {
303	      listed = const [];
304	    }
305	    for (final e in listed) {
306	      if (e.isDir) {
307	        continue;
308	      }
309	      if (!keep.contains(e.name)) {
310	        try {
311	          await client.fsDelete(
312	            CompanionFs.joinRel(McuFsPaths.navptsDir, e.name),
313	          );
314	        } catch (_) {}
315	      }
316	    }
317	    return jobs.length;
318	  }
319	
320	  /// 下发常用点 + 坐标点记录。
321	  static Future<({int favs, int routes})> pushWaypoints(
322	    CompanionClient client, {
323	    void Function(McuSyncProgress p)? onProgress,
324	    int transferred = 0,
325	  }) async {
326	    var xfer = transferred;
327	    void tick(McuSyncProgress p) {
328	      xfer = p.transferred;
329	      onProgress?.call(p);
330	    }
331	
332	    final favs = await pushFavorites(
333	      client,
334	      onProgress: tick,
335	      transferred: xfer,
336	    );
337	    final routes = await pushNavRoutes(
338	      client,
339	      onProgress: tick,
340	      transferred: xfer,
341	    );
342	    return (favs: favs, routes: routes);
343	  }
344	}
