215	  static LatLng? _llFromAttrs(String attrs) {
216	    final lat = double.tryParse(_latAttrRe.firstMatch(attrs)?.group(1) ?? '');
217	    final lon = double.tryParse(_lonAttrRe.firstMatch(attrs)?.group(1) ?? '');
218	    if (lat == null || lon == null) return null;
219	    return LatLng(lat, lon);
220	  }
