222	  static ({double? max, List<RideSeriesPoint> points, List<double> atPoint})
223	      _speedSeries(List<_GpxPt> pts) {
224	    var maxV = 0.0;
225	    final series = <RideSeriesPoint>[];
226	    final atPoint = List<double>.filled(pts.length, 0);
227	    var last = 0.0;
228	    for (var i = 1; i < pts.length; i++) {
229	      var v = last;
230	      final a = pts[i - 1].time;
231	      final b = pts[i].time;
232	      if (a != null && b != null) {
233	        final sec = b.difference(a).inMilliseconds / 1000.0;
234	        if (sec >= 0.8 && sec <= 60) {
235	          final km = _haversineKm(pts[i - 1].ll, pts[i].ll);
236	          final raw = km / (sec / 3600.0);
237	          if (raw > 0 && raw < 80) {
238	            v = raw;
239	            series.add(RideSeriesPoint(time: b, value: v));
240	            if (v > maxV) maxV = v;
241	          }
242	        }
243	      }
244	      atPoint[i] = v;
245	      last = v;
246	    }
247	    return (
248	      max: maxV > 0.5 ? maxV : null,
249	      points: series,
250	      atPoint: atPoint,
251	    );
252	  }
