254	  /// 沿轨迹每整公里一个点。
255	  static List<({LatLng ll, int km})> kmMarkers(
256	    List<LatLng> points, {
257	    double intervalKm = 1,
258	    int maxMarks = 120,
259	  }) {
260	    final out = <({LatLng ll, int km})>[];
261	    if (points.length < 2 || intervalKm <= 0) return out;
262	    var acc = 0.0;
263	    var next = intervalKm;
264	    var n = 1;
265	    for (var i = 1; i < points.length; i++) {
266	      final d = _haversineKm(points[i - 1], points[i]);
267	      if (d <= 0) continue;
268	      while (acc + d >= next && n <= maxMarks) {
269	        final t = ((next - acc) / d).clamp(0.0, 1.0);
270	        final a = points[i - 1];
271	        final b = points[i];
272	        out.add((
273	          ll: LatLng(
274	            a.latitude + (b.latitude - a.latitude) * t,
275	            a.longitude + (b.longitude - a.longitude) * t,
276	          ),
277	          km: n,
278	        ));
279	        n++;
280	        next += intervalKm;
281	      }
282	      acc += d;
283	    }
284	    return out;
285	  }
