287	  static ({int? avg, int? max, List<RideSeriesPoint> points}) _hrSeries(
288	    List<_GpxPt> pts,
289	  ) {
290	    final series = <RideSeriesPoint>[];
291	    var sum = 0;
292	    var maxV = 0;
293	    for (final p in pts) {
294	      final hr = p.hr;
295	      if (hr == null) continue;
296	      series.add(RideSeriesPoint(time: p.time, value: hr.toDouble()));
297	      sum += hr;
298	      if (hr > maxV) maxV = hr;
299	    }
300	    if (series.isEmpty) {
301	      return (avg: null, max: null, points: const []);
302	    }
303	    return (
304	      avg: (sum / series.length).round(),
305	      max: maxV,
306	      points: series,
307	    );
308	  }
309	
310	  static ({double? gain, double? loss, double? min, double? max}) _elev(
311	    List<_GpxPt> pts,
312	  ) {
313	    double? minV;
314	    double? maxV;
315	    var gain = 0.0;
316	    var loss = 0.0;
317	    double? prev;
318	    var n = 0;
319	    for (final p in pts) {
320	      final e = p.ele;
321	      if (e == null) continue;
322	      n++;
323	      minV = minV == null ? e : math.min(minV, e);
324	      maxV = maxV == null ? e : math.max(maxV, e);
325	      if (prev != null) {
326	        final d = e - prev;
327	        if (d > 0.8) gain += d;
328	        if (d < -0.8) loss += -d;
329	      }
330	      prev = e;
331	    }
332	    if (n < 2) {
333	      return (gain: null, loss: null, min: minV, max: maxV);
334	    }
335	    return (
336	      gain: gain > 0.5 ? gain : null,
337	      loss: loss > 0.5 ? loss : null,
338	      min: minV,
339	      max: maxV,
340	    );
341	  }
