394	  /// 按默认最大心率 190 的五区。
395	  static int hrZoneIndex(int bpm) {
396	    if (bpm < 114) return 0;
397	    if (bpm < 133) return 1;
398	    if (bpm < 152) return 2;
399	    if (bpm < 171) return 3;
400	    return 4;
401	  }
