403	  /// 无热量字段时的估算：有心率用 Keytel 简化，否则按里程。
404	  static int estimateKcal({
405	    int? avgHrBpm,
406	    Duration? duration,
407	    double distanceKm = 0,
408	  }) {
409	    final minutes = (duration?.inSeconds ?? 0) / 60.0;
410	    if (avgHrBpm != null && avgHrBpm > 0 && minutes > 0) {
411	      return math.max(1, (avgHrBpm * minutes * 0.03).round());
412	    }
413	    if (distanceKm > 0.001) {
414	      return math.max(1, (distanceKm * 30).round());
415	    }
416	    return 0;
417	  }
