535	  /// 密轨迹：track。点上写 `<time>`，默认 1 秒一点、最后一点为 [endUtc]。
536	  static String writeTrack({
537	    required String name,
538	    required List<LatLng> points,
539	    DateTime? endUtc,
540	    Duration pointInterval = const Duration(seconds: 1),
541	  }) {
542	    final end = (endUtc ?? DateTime.now()).toUtc();
543	    final n = points.length;
544	    final start = n <= 1
545	        ? end
546	        : end.subtract(pointInterval * (n - 1));
547	    final buf = StringBuffer()
548	      ..writeln('<?xml version="1.0" encoding="UTF-8"?>')
549	      ..writeln(
550	        '<gpx version="1.1" creator="Helm One App" '
551	        'xmlns="http://www.topografix.com/GPX/1/1">',
552	      )
553	      ..writeln(
554	        '  <metadata><name>${_esc(name)}</name>'
555	        '<time>${formatUtc(start)}</time></metadata>',
556	      )
557	      ..writeln('  <trk><name>${_esc(name)}</name><trkseg>');
558	    for (var i = 0; i < n; i++) {
559	      final p = points[i];
560	      final t = start.add(pointInterval * i);
561	      buf.writeln(
562	        '    <trkpt lat="${p.latitude.toStringAsFixed(7)}" '
563	        'lon="${p.longitude.toStringAsFixed(7)}">'
564	        '<time>${formatUtc(t)}</time></trkpt>',
565	      );
566	    }
567	    buf.writeln('  </trkseg></trk></gpx>');
568	    return buf.toString();
569	  }
