571	  /// 码表 FS 的 mtime 不可信。文件里若没有可信 `<time>`，用手机时钟补上。
572	  /// 已有 GNSS/App 时间则原样返回，不改 ele / 扩展字段。
573	  static String ensureTimestamps(String xml, {DateTime? nowUtc}) {
574	    if (plausibleTimes(xml).isNotEmpty) {
575	      return xml;
576	    }
577	    final now = (nowUtc ?? DateTime.now()).toUtc();
578	    var n = _trkptRe.allMatches(xml).length;
579	    if (n == 0) {
580	      n = _trkptSelfRe.allMatches(xml).length;
581	    }
582	    final start = n <= 1 ? now : now.subtract(Duration(seconds: n - 1));
583	    var out = _stampTrkpts(xml, now);
584	    out = _ensureMetadataTime(out, start);
585	    return out;
586	  }
