588	  static String _stampTrkpts(String xml, DateTime endUtc) {
589	    final blocks = _trkptRe.allMatches(xml).toList();
590	    if (blocks.isEmpty) {
591	      return _stampSelfClosing(xml, endUtc);
592	    }
593	    final n = blocks.length;
594	    final start = n <= 1
595	        ? endUtc
596	        : endUtc.subtract(Duration(seconds: n - 1));
597	    var out = xml;
598	    for (var i = n - 1; i >= 0; i--) {
599	      final m = blocks[i];
600	      final t = formatUtc(start.add(Duration(seconds: i)));
601	      out = out.replaceRange(m.start, m.end, _stampOneTrkpt(m.group(0)!, t));
602	    }
603	    return out;
604	  }
605	
606	  static String _stampSelfClosing(String xml, DateTime endUtc) {
607	    final blocks = _trkptSelfRe.allMatches(xml).toList();
608	    if (blocks.isEmpty) return xml;
609	    final n = blocks.length;
610	    final start = n <= 1
611	        ? endUtc
612	        : endUtc.subtract(Duration(seconds: n - 1));
613	    var out = xml;
614	    for (var i = n - 1; i >= 0; i--) {
615	      final m = blocks[i];
616	      final attrs = m.group(1) ?? '';
617	      final t = formatUtc(start.add(Duration(seconds: i)));
618	      out = out.replaceRange(
619	        m.start,
620	        m.end,
621	        '<trkpt$attrs><time>$t</time></trkpt>',
622	      );
623	    }
624	    return out;
625	  }
626	
627	  static String _stampOneTrkpt(String block, String iso) {
628	    if (_timeRe.hasMatch(block)) {
629	      return block.replaceFirst(_timeRe, '<time>$iso</time>');
630	    }
631	    return block.replaceFirst(
632	      RegExp(r'</trkpt>', caseSensitive: false),
633	      '<time>$iso</time></trkpt>',
634	    );
635	  }
636	
637	  static String _ensureMetadataTime(String xml, DateTime t) {
638	    final iso = formatUtc(t);
639	    final meta = _metaOpenRe.firstMatch(xml);
640	    if (meta != null) {
641	      final closeIdx = xml.toLowerCase().indexOf('</metadata>', meta.end);
642	      if (closeIdx > meta.end) {
643	        final inner = xml.substring(meta.end, closeIdx);
644	        if (_timeRe.hasMatch(inner)) {
645	          final stamped = inner.replaceFirst(_timeRe, '<time>$iso</time>');
646	          return xml.substring(0, meta.end) + stamped + xml.substring(closeIdx);
647	        }
648	        return '${xml.substring(0, meta.end)}<time>$iso</time>${xml.substring(meta.end)}';
649	      }
650	    }
651	    final gpx = _gpxOpenRe.firstMatch(xml);
652	    if (gpx == null) return xml;
653	    return '${xml.substring(0, gpx.end)}\n'
654	        '  <metadata><time>$iso</time></metadata>'
655	        '${xml.substring(gpx.end)}';
656	  }
657	
658	  /// 改 GPX 里的 `<name>`，没有则写入 metadata。分享 / 码表列表跟这个走。
659	  static String setName(String xml, String name) {
660	    final esc = _esc(name.trim());
661	    if (esc.isEmpty) return xml;
662	    if (_nameRe.hasMatch(xml)) {
663	      return xml.replaceAll(_nameRe, '<name>$esc</name>');
664	    }
665	    final meta = _metaOpenRe.firstMatch(xml);
666	    if (meta != null) {
667	      return '${xml.substring(0, meta.end)}<name>$esc</name>${xml.substring(meta.end)}';
668	    }
669	    final gpx = _gpxOpenRe.firstMatch(xml);
670	    if (gpx == null) return xml;
671	    return '${xml.substring(0, gpx.end)}\n'
672	        '  <metadata><name>$esc</name></metadata>'
673	        '${xml.substring(gpx.end)}';
674	  }
675	
676	  /// 码表列表文件名上限约 31 字符（含 .gpx）。
677	  static String safeFileName(String raw, {int maxChars = 31}) {
678	    var stem = raw.trim();
679	    if (stem.toLowerCase().endsWith('.gpx')) {
680	      stem = stem.substring(0, stem.length - 4);
681	    }
682	    final buf = StringBuffer();
683	    for (final r in stem.runes) {
684	      final c = String.fromCharCode(r);
685	      if (RegExp(r'[A-Za-z0-9._\u4e00-\u9fff-]').hasMatch(c)) {
686	        buf.write(c);
687	      } else if (c == ' ') {
688	        buf.write('_');
689	      }
690	    }
691	    var out = buf.toString();
692	    if (out.isEmpty) {
693	      out = 'route';
694	    }
695	    const ext = '.gpx';
696	    final cap = maxChars - ext.length;
697	    if (out.length > cap) {
698	      out = out.substring(0, cap);
699	    }
700	    return '$out$ext';
701	  }
702	
703	  /// 坐标点记录文件名（`.tsv`）。[maxChars] 按 UTF-8 字节计，给码表 `dirent` 留余量。
704	  static String safeTsvFileName(String raw, {int maxChars = 40}) {
705	    var stem = raw.trim();
706	    if (stem.toLowerCase().endsWith('.tsv')) {
707	      stem = stem.substring(0, stem.length - 4);
708	    }
709	    final buf = StringBuffer();
710	    for (final r in stem.runes) {
711	      final c = String.fromCharCode(r);
712	      if (RegExp(r'[A-Za-z0-9._\u4e00-\u9fff-]').hasMatch(c)) {
713	        buf.write(c);
714	      } else if (c == ' ') {
715	        buf.write('_');
716	      }
717	    }
718	    var out = buf.toString();
719	    if (out.isEmpty) {
720	      out = 'route';
721	    }
722	    const ext = '.tsv';
723	    final cap = maxChars - ext.length;
724	    out = WaypointTsv.capUtf8(out, cap > 1 ? cap : 1);
725	    return '$out$ext';
726	  }
727	
728	  static String _esc(String s) => s
729	      .replaceAll('&', '&amp;')
730	      .replaceAll('<', '&lt;')
731	      .replaceAll('>', '&gt;')
732	      .replaceAll('"', '&quot;');
733	}
