81	/// 本机坐标点库。同步时覆盖码表 `mtp/navpts/`。
82	class NavRouteStore {
83	  factory NavRouteStore() => _instance;
84	  static final NavRouteStore _instance = NavRouteStore._();
85	  NavRouteStore._();
86	
87	  File? _file;
88	  final List<NavRouteRecord> _items = [];
89	
90	  List<NavRouteRecord> get items => List.unmodifiable(_items);
91	
92	  Future<File> _ensure() async {
93	    if (_file != null) return _file!;
94	    final root = await getApplicationDocumentsDirectory();
95	    _file = File(p.join(root.path, 'nav_routes.json'));
96	    return _file!;
97	  }
98	
99	  Future<void> load() async {
100	    final f = await _ensure();
101	    _items.clear();
102	    if (!await f.exists()) return;
103	    try {
104	      final raw = jsonDecode(await f.readAsString());
105	      if (raw is List) {
106	        for (final e in raw) {
107	          if (e is Map<String, dynamic>) {
108	            _items.add(NavRouteRecord.fromJson(Map<String, Object?>.from(e)));
109	          }
110	        }
111	      }
112	    } catch (_) {
113	      _items.clear();
114	    }
115	    _items.sort((a, b) => b.updatedMs.compareTo(a.updatedMs));
116	  }
117	
118	  Future<void> _flush() async {
119	    final f = await _ensure();
120	    await f.writeAsString(
121	      jsonEncode(_items.map((e) => e.toJson()).toList()),
122	    );
123	  }
124	
125	  NavRouteRecord? find(String id) {
126	    for (final e in _items) {
127	      if (e.id == id) return e;
128	    }
129	    return null;
130	  }
131	
132	  Future<void> upsert(NavRouteRecord rec) async {
133	    rec.updatedMs = DateTime.now().millisecondsSinceEpoch;
134	    final i = _items.indexWhere((e) => e.id == rec.id);
135	    if (i >= 0) {
136	      _items[i] = rec;
137	    } else {
138	      _items.insert(0, rec);
139	    }
140	    _items.sort((a, b) => b.updatedMs.compareTo(a.updatedMs));
141	    await _flush();
142	  }
143	
144	  Future<void> remove(String id) async {
145	    _items.removeWhere((e) => e.id == id);
146	    await _flush();
147	  }
148	}
