2	
3	import 'package:latlong2/latlong.dart';
4	
5	/// WGS-84 ↔ GCJ-02（火星坐标）。国内高德底图按 GCJ-02 编号瓦片。
6	abstract class ChinaCoord {
7	  static const _a = 6378245.0;
8	  static const _ee = 0.00669342162296594323;
9	
10	  /// 是否可视为境外（不做偏移）。
11	  static bool outOfChina(double lat, double lon) =>
12	      lon < 72.004 || lon > 137.8347 || lat < 0.8293 || lat > 55.8271;
13	
14	  /// GPS / GPX 用的 WGS-84 → 高德图上的 GCJ-02。
15	  static LatLng wgs84ToGcj02(LatLng p) {
16	    final lat = p.latitude;
17	    final lon = p.longitude;
18	    if (outOfChina(lat, lon)) return p;
19	    final d = _delta(lat, lon);
20	    return LatLng(lat + d.$1, lon + d.$2);
21	  }
22	
23	  /// 地图点选（GCJ-02）→ 存盘 / 路网用的 WGS-84。
24	  static LatLng gcj02ToWgs84(LatLng p) {
25	    final lat = p.latitude;
26	    final lon = p.longitude;
27	    if (outOfChina(lat, lon)) return p;
28	    var wgsLat = lat;
29	    var wgsLon = lon;
30	    for (var i = 0; i < 4; i++) {
31	      final d = _delta(wgsLat, wgsLon);
32	      wgsLat = lat - d.$1;
33	      wgsLon = lon - d.$2;
34	    }
35	    return LatLng(wgsLat, wgsLon);
36	  }
37	
38	  static (double dLat, double dLon) _delta(double lat, double lon) {
39	    final dLat = _transformLat(lon - 105.0, lat - 35.0);
40	    final dLon = _transformLon(lon - 105.0, lat - 35.0);
41	    final radLat = lat / 180.0 * math.pi;
42	    var magic = math.sin(radLat);
43	    magic = 1 - _ee * magic * magic;
44	    final sqrtMagic = math.sqrt(magic);
45	    final latOff = (dLat * 180.0) /
46	        ((_a * (1 - _ee)) / (magic * sqrtMagic) * math.pi);
47	    final lonOff =
48	        (dLon * 180.0) / (_a / sqrtMagic * math.cos(radLat) * math.pi);
49	    return (latOff, lonOff);
50	  }
51	
52	  static double _transformLat(double x, double y) {
53	    var r = -100.0 +
54	        2.0 * x +
55	        3.0 * y +
56	        0.2 * y * y +
57	        0.1 * x * y +
58	        0.2 * math.sqrt(x.abs());
59	    r += (20.0 * math.sin(6.0 * x * math.pi) +
60	            20.0 * math.sin(2.0 * x * math.pi)) *
61	        2.0 /
62	        3.0;
63	    r += (20.0 * math.sin(y * math.pi) + 40.0 * math.sin(y / 3.0 * math.pi)) *
64	        2.0 /
65	        3.0;
66	    r += (160.0 * math.sin(y / 12.0 * math.pi) +
67	            320.0 * math.sin(y * math.pi / 30.0)) *
68	        2.0 /
69	        3.0;
70	    return r;
71	  }
72	
73	  static double _transformLon(double x, double y) {
74	    var r = 300.0 +
75	        x +
76	        2.0 * y +
77	        0.1 * x * x +
78	        0.1 * x * y +
79	        0.1 * math.sqrt(x.abs());
80	    r += (20.0 * math.sin(6.0 * x * math.pi) +
81	            20.0 * math.sin(2.0 * x * math.pi)) *
82	        2.0 /
83	        3.0;
84	    r += (20.0 * math.sin(x * math.pi) + 40.0 * math.sin(x / 3.0 * math.pi)) *
85	        2.0 /
86	        3.0;
87	    r += (150.0 * math.sin(x / 12.0 * math.pi) +
88	            300.0 * math.sin(x / 30.0 * math.pi)) *
89	        2.0 /
90	        3.0;
91	    return r;
92	  }
93	}
