14	/// 一座城市的本机下载进度。
15	class OsmCityStatus {
16	  /// 创建状态。
17	  const OsmCityStatus({
18	    required this.city,
19	    required this.have,
20	    required this.bytes,
21	    required this.expected,
22	  });
23	
24	  final OsmCity city;
25	  final int have;
26	  final int bytes;
27	  final int expected;
28	
29	  bool get isComplete => expected > 0 && have >= (expected * 0.98).floor();
30	
31	  bool get isPartial => have > 0 && !isComplete;
32	
33	  bool get isEmpty => have <= 0;
34	
35	  double get ratio => expected <= 0 ? 0 : (have / expected).clamp(0.0, 1.0);
36	}
37	
38	/// 手动下载城市瓦片（国内高德源），并统计是否下完。
39	class OsmCityStore extends ChangeNotifier {
40	  OsmCityStore._();
41	
42	  /// 单例。后台下载离开页面也继续。
43	  static final OsmCityStore instance = OsmCityStore._();
44	
45	  static const _ua = '${AppKeys.appName} (${AppKeys.androidPackage})';
46	
47	  String? _activeId;
48	  int _done = 0;
49	  int _total = 0;
50	  bool _cancel = false;
51	  String? _error;
52	  bool _running = false;
53	
54	  /// 正在下的城市 id。
55	  String? get activeId => _activeId;
56	
57	  int get done => _done;
58	
59	  int get total => _total;
60	
61	  bool get running => _running;
62	
63	  String? get error => _error;
64	
65	  Future<File> _indexFile() async {
66	    final root = await AppCacheStore.instance.subdir('osm');
67	    return File(p.join(root.path, 'cities.json'));
68	  }
69	
70	  Future<Map<String, dynamic>> _readIndex() async {
71	    final f = await _indexFile();
72	    if (!await f.exists()) return {};
73	    try {
74	      final raw = jsonDecode(utf8.decode(await f.readAsBytes()));
75	      if (raw is Map<String, dynamic>) return raw;
76	      if (raw is Map) {
77	        return raw.map((k, v) => MapEntry('$k', v));
78	      }
79	    } catch (_) {}
80	    return {};
81	  }
82	
83	  Future<void> _writeIndex(Map<String, dynamic> idx) async {
84	    final f = await _indexFile();
85	    await f.writeAsString(const JsonEncoder.withIndent('  ').convert(idx));
86	  }
87	
88	  /// 扫描一座城市当前磁盘上的张数与体积。
89	  Future<OsmCityStatus> statusOf(OsmCity city) async {
90	    await OsmFileCache.instance.init();
91	    final tiles = OsmTileMath.tilesInBounds(
92	      southWest: city.gcjSouthWest,
93	      northEast: city.gcjNorthEast,
94	      minZoom: city.minZoom,
95	      maxZoom: city.maxZoom,
96	    );
97	    var have = 0;
98	    var bytes = 0;
99	    for (final t in tiles) {
100	      final f = OsmFileCache.instance.fileFor(t.$1, t.$2, t.$3);
101	      if (await f.exists()) {
102	        have++;
103	        bytes += await f.length();
104	      }
105	    }
106	    return OsmCityStatus(
107	      city: city,
108	      have: have,
109	      bytes: bytes,
110	      expected: tiles.length,
111	    );
112	  }
113	
114	  /// 已开始过的城市（索引里有记录，或磁盘上已有瓦片）。
115	  Future<List<OsmCityStatus>> downloaded() async {
116	    final idx = await _readIndex();
117	    final out = <OsmCityStatus>[];
118	    for (final id in idx.keys) {
119	      final city = OsmCityCatalog.byId(id);
120	      if (city == null) continue;
121	      out.add(await statusOf(city));
122	    }
123	    out.sort((a, b) {
124	      if (a.isComplete != b.isComplete) return a.isComplete ? -1 : 1;
125	      return a.city.name.compareTo(b.city.name);
126	    });
127	    return out;
128	  }
129	
130	  /// 已下完的座数（读索引，不扫磁盘）。
131	  Future<int> completeCount() async {
132	    final idx = await _readIndex();
133	    var n = 0;
134	    for (final v in idx.values) {
135	      if (v is! Map) continue;
136	      final have = (v['have'] as num?)?.toInt() ?? 0;
137	      final expected = (v['expected'] as num?)?.toInt() ?? 0;
138	      final cancelled = v['cancelled'] == true;
139	      if (!cancelled &&
140	          expected > 0 &&
141	          have >= (expected * 0.98).floor()) {
142	        n++;
143	      }
144	    }
145	    return n;
146	  }
147	
148	  /// 开始或续传。同时只能下一座。
149	  Future<void> download(OsmCity city) async {
150	    if (_running) return;
151	    _running = true;
152	    _cancel = false;
153	    _error = null;
154	    _activeId = city.id;
155	    notifyListeners();
156	
157	    final client = HttpClient();
158	    client.userAgent = _ua;
159	    client.connectionTimeout = const Duration(seconds: 12);
160	
161	    try {
162	      await OsmFileCache.instance.init();
163	      final tiles = OsmTileMath.tilesInBounds(
164	        southWest: city.gcjSouthWest,
165	        northEast: city.gcjNorthEast,
166	        minZoom: city.minZoom,
167	        maxZoom: city.maxZoom,
168	      );
169	      _total = tiles.length;
170	      _done = 0;
171	
172	      const workers = 4;
173	      var cursor = 0;
174	
175	      Future<void> worker() async {
176	        while (true) {
177	          if (_cancel) return;
178	          final i = cursor++;
179	          if (i >= tiles.length) return;
180	          final t = tiles[i];
181	          final file = await OsmFileCache.instance.ensureFile(t.$1, t.$2, t.$3);
182	          if (await file.exists() && await file.length() > 32) {
183	            _done++;
184	            if (_done % 8 == 0) notifyListeners();
185	            continue;
186	          }
187	          final url = HelmOsmTiles.tileUrl(t.$1, t.$2, t.$3);
188	          try {
189	            final req = await client.getUrl(Uri.parse(url));
190	            req.headers.set('Referer', HelmOsmTiles.referer);
191	            final res = await req.close().timeout(const Duration(seconds: 20));
192	            if (res.statusCode != 200) {
193	              _done++;
194	              continue;
195	            }
196	            final bytes = await res.fold<List<int>>(
197	              <int>[],
198	              (p, e) => p..addAll(e),
199	            );
200	            if (bytes.length >= 32 && bytes[0] == 0x89 && bytes[1] == 0x50) {
201	              await file.writeAsBytes(bytes, flush: false);
202	            }
203	          } catch (_) {
204	            // 单张失败不中断整城；可再续传。
205	          }
206	          _done++;
207	          if (_done % 4 == 0) notifyListeners();
208	        }
209	      }
210	
211	      await Future.wait(List.generate(workers, (_) => worker()));
212	
213	      final st = await statusOf(city);
214	      final idx = await _readIndex();
215	      idx[city.id] = {
216	        'have': st.have,
217	        'expected': st.expected,
218	        'bytes': st.bytes,
219	        'updatedAt': DateTime.now().toIso8601String(),
220	        'cancelled': _cancel,
221	      };
222	      await _writeIndex(idx);
223	    } catch (e, st) {
224	      await AppLog.e('OsmCity', e, st);
225	      _error = 'failed';
226	    } finally {
227	      client.close(force: true);
228	      _running = false;
229	      _activeId = null;
230	      notifyListeners();
231	    }
232	  }
233	
234	  /// 停止当前下载（已写入的瓦片保留，可续传）。
235	  void cancel() {
236	    _cancel = true;
237	  }
238	
239	  /// 只从已下载列表去掉记录，不删共享瓦片文件。
240	  Future<void> forget(String id) async {
241	    final idx = await _readIndex();
242	    idx.remove(id);
243	    await _writeIndex(idx);
244	    notifyListeners();
245	  }
246	}
