1	import 'dart:convert';
2	import 'dart:io';
3	import 'dart:typed_data';
4	
5	import 'package:sifli_companion/gnss/rinex_mga.dart';
6	import 'package:sifli_companion/log/app_log.dart';
7	
8	/// 从公开 IGS 镜像拉当天（或昨天）的 MIXED BRDC。
9	class EphBrdc {
10	  /// 创建下载器。
11	  EphBrdc({HttpClient? http}) : _http = http ?? HttpClient() {
12	    _http.userAgent = 'HelmOne/1.0 (companion GNSS BRDC)';
13	    _http.connectionTimeout = const Duration(seconds: 15);
14	  }
15	
16	  static const _tag = 'EphBrdc';
17	  static const _bkgRoot = 'https://igs.bkg.bund.de/root_ftp/IGS/BRDC';
18	
19	  final HttpClient _http;
20	
21	  /// 下载并转成 UBX-MGA。
22	  Future<Uint8List> fetchAndBuild({
23	    DateTime? now,
24	    void Function(String url)? onUrl,
25	  }) async {
26	    final utc = (now ?? DateTime.now()).toUtc();
27	    final days = [utc, utc.subtract(const Duration(days: 1))];
28	    Object? last;
29	    for (final day in days) {
30	      final urls = <Uri>[
31	        ...await _listBkg(day),
32	        ...urisFor(day),
33	      ];
34	      final seen = <String>{};
35	      for (final url in urls) {
36	        if (!seen.add(url.toString())) continue;
37	        onUrl?.call(url.toString());
38	        try {
39	          final raw = await _get(url);
40	          final mga = RinexMga.convertBytes(raw, now: utc);
41	          await AppLog.i(_tag, 'BRDC $url -> ${mga.length} B');
42	          return mga;
43	        } catch (e) {
44	          last = e;
45	          await AppLog.w(_tag, 'BRDC skip $url: $e');
46	        }
47	      }
48	    }
49	    throw RinexMgaException('下载广播星历失败：${last ?? '无镜像'}');
50	  }
51	
52	  /// 某日 BKG 上常见文件名（目录列表失败时的兜底）。
53	  static List<Uri> urisFor(DateTime utc) {
54	    final yyyy = utc.year.toString().padLeft(4, '0');
55	    final doy = _doy(utc);
56	    final tag = '$yyyy${doy}0000';
57	    const names = [
58	      'BRDC00IGS',
59	      'BRDC00WRD',
60	      'BRD400DLR',
61	      'BRDM00DLR',
62	    ];
63	    return [
64	      for (final n in names)
65	        for (final kind in ['R', 'S'])
66	          Uri.parse('$_bkgRoot/$yyyy/$doy/${n}_${kind}_${tag}_01D_MN.rnx.gz'),
67	    ];
68	  }
69	
70	  static String _doy(DateTime utc) {
71	    final jan1 = DateTime.utc(utc.year);
72	    return (utc.difference(jan1).inDays + 1).toString().padLeft(3, '0');
73	  }
74	
75	  Future<List<Uri>> _listBkg(DateTime utc) async {
76	    final yyyy = utc.year.toString().padLeft(4, '0');
77	    final doy = _doy(utc);
78	    final dir = Uri.parse('$_bkgRoot/$yyyy/$doy/');
79	    try {
80	      final html = utf8.decode(await _get(dir, allowHtml: true));
81	      final names = RegExp(
82	        r'href="([^"]+_01D_MN\.rnx\.gz)"',
83	        caseSensitive: false,
84	      ).allMatches(html).map((m) => m.group(1)!).toSet().toList();
85	      names.sort((a, b) => _score(b).compareTo(_score(a)));
86	      return [for (final n in names) dir.resolve(n)];
87	    } catch (e) {
88	      await AppLog.w(_tag, 'BRDC list $dir: $e');
89	      return const [];
90	    }
91	  }
92	
93	  static int _score(String name) {
94	    var s = 0;
95	    if (name.contains('_R_')) s += 20;
96	    if (name.contains('IGS')) s += 10;
97	    if (name.contains('WRD')) s += 8;
98	    if (name.startsWith('BRDC')) s += 5;
99	    return s;
100	  }
101	
102	  Future<Uint8List> _get(Uri uri, {bool allowHtml = false}) async {
103	    final req = await _http.getUrl(uri);
104	    req.followRedirects = true;
105	    req.maxRedirects = 5;
106	    final res = await req.close().timeout(const Duration(seconds: 25));
107	    if (res.statusCode < 200 || res.statusCode >= 300) {
108	      await res.drain<void>();
109	      throw HttpException('HTTP ${res.statusCode}', uri: uri);
110	    }
111	    final builder = BytesBuilder(copy: false);
112	    await for (final chunk in res) {
113	      builder.add(chunk);
114	      if (builder.length > 8 * 1024 * 1024) {
115	        throw const RinexMgaException('星历文件过大');
116	      }
117	    }
118	    final bytes = Uint8List.fromList(builder.takeBytes());
119	    if (bytes.length < 64) {
120	      throw const RinexMgaException('星历文件太小');
121	    }
122	    if (!allowHtml && bytes[0] == 0x3c) {
123	      throw const RinexMgaException('镜像返回了网页而不是星历');
124	    }
125	    return bytes;
126	  }
127	}
