1	import 'dart:convert';
2	import 'dart:io';
3	import 'dart:math' as math;
4	
5	import 'package:latlong2/latlong.dart';
6	import 'package:sifli_companion/app/app_keys.dart';
7	
8	/// 路网吸附与两点之间沿道路补点（BRouter + OSRM，用法对齐 gpx.studio）。
9	class RoadRouter {
10	  RoadRouter._();
11	  static final RoadRouter instance = RoadRouter._();
12	
13	  static const snapMaxMeters = 200.0;
14	
15	  static const _ua = '${AppKeys.appName} (${AppKeys.androidPackage})';
16	
17	  /// 结果缓存条数上限。编辑一条件路线时会反复吸附同一个点、重算同一段路
18	  /// （排序 / 删除 / 撤销之后大部分路段其实没变），没有缓存就每次重走公网。
19	  static const _maxCached = 240;
20	
21	  final _snapCache = <String, LatLng>{};
22	  final _legCache = <String, List<LatLng>>{};
23	
24	  static void _remember<K, V>(Map<K, V> cache, K key, V value) {
25	    cache[key] = value;
26	    if (cache.length > _maxCached) cache.remove(cache.keys.first);
27	  }
28	
29	  /// 约 1.1 m 精度：同一颗钉子重算时必然命中，手指也不会点出更细的差别。
30	  static String _key(LatLng p) =>
31	      '${p.latitude.toStringAsFixed(5)},${p.longitude.toStringAsFixed(5)}';
32	
33	  /// 把点击吸到最近道路。太远则抛 [RoadRouterException]。
34	  Future<LatLng> snap(LatLng tap) async {
35	    final cached = _snapCache[_key(tap)];
36	    if (cached != null) return cached;
37	
38	    final uri = Uri.https(
39	      'router.project-osrm.org',
40	      '/nearest/v1/driving/${tap.longitude},${tap.latitude}',
41	      {'number': '1'},
42	    );
43	    final json = await _getJson(uri);
44	    final snapped = parseOsrmNearest(json, tap);
45	    if (snapped == null) {
46	      throw const RoadRouterException('no road');
47	    }
48	    _remember(_snapCache, _key(tap), snapped);
49	    return snapped;
50	  }
51	
52	  /// 吸附，但失败不抛：网络不通或离路太远都退化成「就用你点的位置」。
53	  ///
54	  /// 编辑界面里因为一次超时把用户刚点的位置吞掉是最糟的选择 —— 点在哪就放在哪，
55	  /// 由调用方按 [RoadSnapResult.error] 提示一句并记日志。
56	  Future<RoadSnapResult> snapOrKeep(LatLng tap) async {
57	    try {
58	      return RoadSnapResult(await snap(tap));
59	    } on RoadRouterException {
60	      return RoadSnapResult(tap, kept: true);
61	    } catch (e, st) {
62	      return RoadSnapResult(tap, kept: true, error: e, stack: st);
63	    }
64	  }
65	
66	  /// 两点之间沿路网的折线（含起终点）。骑行剖面优先 BRouter。
67	  Future<List<LatLng>> route(LatLng from, LatLng to) async {
68	    final key = '${_key(from)}|${_key(to)}';
69	    final cached = _legCache[key];
70	    if (cached != null) return cached;
