91	  /// 途经点串成完整路网折线。
92	  ///
93	  /// 各段互不依赖，[Future.wait] 并行发。串行时 N 个点要排 N-1 个来回
94	  /// （公网 OSRM/BRouter 单段实测 1.6–1.9 s），点一下就要干等好几秒 —— 这正是
95	  /// 「选点后像卡住」的主因；并行后整条重建只等最慢的一段。
96	  Future<List<LatLng>> routeAnchors(List<LatLng> anchors) async {
97	    if (anchors.length < 2) return List<LatLng>.from(anchors);
98	    final legs = await Future.wait([
99	      for (var i = 1; i < anchors.length; i++)
100	        route(anchors[i - 1], anchors[i]),
101	    ]);
102	    final out = <LatLng>[anchors.first];
103	    for (var i = 0; i < legs.length; i++) {
104	      final leg = legs[i];
105	      if (leg.length >= 2) {
106	        out.addAll(leg.skip(1));
107	      } else {
108	        out.add(anchors[i + 1]);
109	      }
110	    }
111	    return out;
112	  }
