135	  Future<Object?> _getJson(Uri uri) async {
136	    final client = HttpClient();
137	    try {
138	      client.userAgent = _ua;
139	      client.connectionTimeout = const Duration(seconds: 12);
140	      final req = await client.getUrl(uri);
