153	  /// OSRM `/nearest`：距离超过 [snapMaxMeters] 视为失败。
154	  static LatLng? parseOsrmNearest(Object? json, LatLng tap) {
155	    if (json is! Map) return null;
156	    if (json['code'] != 'Ok') return null;
157	    final wps = json['waypoints'];
158	    if (wps is! List || wps.isEmpty) return null;
159	    final wp = wps.first;
160	    if (wp is! Map) return null;
161	    final loc = wp['location'];
162	    if (loc is! List || loc.length < 2) return null;
163	    final lon = (loc[0] as num).toDouble();
164	    final lat = (loc[1] as num).toDouble();
165	    final dist = (wp['distance'] as num?)?.toDouble() ??
166	        _haversineM(tap, LatLng(lat, lon));
167	    if (dist > snapMaxMeters) return null;
168	    return LatLng(lat, lon);
169	  }
