171	  static List<LatLng> parseBrouterGeoJson(Object? json) {
172	    if (json is! Map) return const [];
173	    final features = json['features'];
174	    if (features is! List || features.isEmpty) return const [];
175	    final feat = features.first;
176	    if (feat is! Map) return const [];
177	    final geom = feat['geometry'];
178	    if (geom is! Map) return const [];
179	    return _coordsToLatLng(geom['coordinates']);
180	  }
181	
182	  static List<LatLng> parseOsrmRoute(Object? json) {
183	    if (json is! Map) return const [];
184	    if (json['code'] != 'Ok') return const [];
185	    final routes = json['routes'];
186	    if (routes is! List || routes.isEmpty) return const [];
187	    final route = routes.first;
188	    if (route is! Map) return const [];
189	    final geom = route['geometry'];
190	    if (geom is! Map) return const [];
191	    return _coordsToLatLng(geom['coordinates']);
192	  }
193	
194	  static List<LatLng> _coordsToLatLng(Object? raw) {
195	    if (raw is! List) return const [];
196	    final out = <LatLng>[];
197	    for (final c in raw) {
198	      if (c is! List || c.length < 2) continue;
199	      final lon = (c[0] as num).toDouble();
200	      final lat = (c[1] as num).toDouble();
201	      if (out.isNotEmpty) {
202	        final prev = out.last;
203	        if ((prev.latitude - lat).abs() < 1e-8 &&
204	            (prev.longitude - lon).abs() < 1e-8) {
205	          continue;
206	        }
207	      }
208	      out.add(LatLng(lat, lon));
209	    }
210	    return out;
211	  }
212	
213	  static double _haversineM(LatLng a, LatLng b) {
214	    const r = 6371000.0;
215	    final dLat = _rad(b.latitude - a.latitude);
216	    final dLon = _rad(b.longitude - a.longitude);
217	    final x = math.sin(dLat / 2) * math.sin(dLat / 2) +
218	        math.cos(_rad(a.latitude)) *
219	            math.cos(_rad(b.latitude)) *
220	            math.sin(dLon / 2) *
221	            math.sin(dLon / 2);
222	    return 2 * r * math.asin(math.min(1, math.sqrt(x)));
223	  }
224	
225	  static double _rad(double deg) => deg * math.pi / 180;
226	}
