79	    final uri = OtaConfig.manifestUri(hardware: hardware);
80	    await AppLog.i(_tag, 'GET $uri');
81	    final got = await _getString(uri);
82	    final decoded = jsonDecode(got.body);
83	    if (decoded is! Map) {
84	      throw const FormatException('firmware.json 不是对象');
85	    }
86	    var manifest = OtaManifest.fromJson(Map<String, dynamic>.from(decoded));
87	    if (manifest.date.isEmpty && got.modified != null) {
88	      manifest = manifest.copyWith(date: OtaManifest.formatDay(got.modified!));
