93	  Future<Uint8List> downloadFirmware(
94	    OtaManifest manifest, {
95	    void Function(int done, int total)? onProgress,
96	    bool Function()? shouldStop,
97	  }) async {
98	    lastFromCache = false;
99	    final cached = await _loadCache(manifest);
100	    if (cached != null) {
101	      lastFromCache = true;
102	      onProgress?.call(cached.length, cached.length);
103	      return cached;
104	    }
