106	    final primary = manifest.downloadUri;
107	    try {
108	      return await _downloadAndCache(
109	        primary,
110	        manifest,
111	        onProgress: onProgress,
112	        shouldStop: shouldStop,
113	      );
114	    } catch (e) {
115	      final original = Uri.parse(manifest.url);
116	      if (primary != original) {
117	        await AppLog.w(_tag, 'https 下载失败，改走清单原地址: $e');
118	        return _downloadAndCache(
119	          original,
120	          manifest,
121	          onProgress: onProgress,
122	          shouldStop: shouldStop,
123	        );
124	      }
125	      rethrow;
126	    }
