39	  Future<void> _sync() async {
40	    if (!controller.isReady) {
41	      AppTheme.snack(
42	        LocaleKeys.bleSnackbarTitle.tr,
43	        LocaleKeys.deviceNeedConnect.tr,
44	      );
45	      return;
46	    }
47	    final st = controller.status.value;
48	    if (st != null && st.isTransferBusy) {
49	      AppTheme.snack(
50	        LocaleKeys.deviceSync.tr,
51	        LocaleKeys.deviceMtpBusy.tr,
52	      );
53	      return;
54	    }
55	    final center = TransferCenter.to;
56	    if (center.isKindRunning(_syncKind)) return;
57	
58	    controller.syncing.value = true;
59	    controller.syncProg.value =
60	        const McuSyncProgress(phase: McuSyncPhase.listing);
61	    controller.syncKbs.value = 0;
62	
63	    final task = center.begin(
64	      title: LocaleKeys.deviceSync.tr,
65	      kind: _syncKind,
66	    );
67	
68	    try {
69	      final n = await McuSync.pullRideRecords(
70	        controller.client,
71	        onProgress: (p) {
72	          // 页面内的计量条（ShellController）和全局悬浮框各要一份。
73	          controller.applySyncProgress(p);
74	          center.progress(
75	            task,
76	            done: p.done,
77	            total: p.total,
78	            transferred: p.transferred,
79	            phase: _syncPhaseLabel(p.phase),
80	          );
81	        },
82	      );
83	      center.finish(
84	        task,
85	        message: n > 0
86	            ? LocaleKeys.syncDone.trParams({'n': '$n'})
87	            : LocaleKeys.syncNone.tr,
88	      );
89	      controller.bumpRides();
90	      AppTheme.snack(
91	        LocaleKeys.deviceSync.tr,
92	        n > 0
93	            ? LocaleKeys.syncDone.trParams({'n': '$n'})
94	            : LocaleKeys.syncNone.tr,
95	      );
96	    } catch (e, st) {
97	      center.fail(task, e);
98	      AppTheme.fail(LocaleKeys.deviceSync.tr, 'DeviceSync', e, st);
99	    } finally {
100	      controller.clearSyncProgress();
101	    }
