20	  static String whenLine(RideRecord rec, GpxSummary? sum) {
21	    final start = sum?.startTime?.toLocal();
22	    final end = sum?.endTime?.toLocal();
23	    if (start != null && end != null) {
24	      final day = _ymd(start);
25	      final a = _hm(start);
26	      final b = _hm(end);
27	      if (start.year == end.year &&
28	          start.month == end.month &&
29	          start.day == end.day) {
30	        return '$day  $a – $b';
31	      }
32	      return '$day $a  ·  ${_ymd(end)} $b';
33	    }
34	    if (rec.mtime <= 0) return '';
35	    final d = DateTime.fromMillisecondsSinceEpoch(rec.mtime * 1000);
36	    return '${_ymd(d)}  ${_hm(d)}';
37	  }
38	
39	  static String shareCaption(RideRecord rec, GpxSummary? sum) {
40	    final bits = <String>[
41	      rec.title,
42	      if ((sum?.distanceKm ?? rec.distanceKm ?? 0) > 0)
43	        '${(sum?.distanceKm ?? rec.distanceKm)!.toStringAsFixed(1)} km',
44	      if (sum?.duration != null) GpxUtil.formatElapsed(sum!.duration!),
45	      if (sum?.avgSpeedKmh != null)
46	        '${sum!.avgSpeedKmh!.toStringAsFixed(1)} km/h',
47	      if (sum?.avgHrBpm != null) '${sum!.avgHrBpm} bpm',
48	    ];
49	    return bits.join(' · ');
50	  }
51	
52	  static String _ymd(DateTime d) {
53	    final y = d.year.toString().padLeft(4, '0');
54	    final m = d.month.toString().padLeft(2, '0');
