6	/// 一次数据抓取 / 传输的生命周期状态。
7	enum TransferStatus {
8	  /// 进行中。
9	  running,
10	
11	  /// 正常结束。
12	  done,
13	
14	  /// 出错结束。
15	  failed,
16	
17	  /// 用户取消。
18	  cancelled,
19	}
20	
21	/// 全局悬浮框里的一条抓取任务。
22	///
23	/// 由 [TransferCenter.begin] 创建，调用方持有它并回调 [TransferCenter.progress] /
24	/// [TransferCenter.finish] 等。字段是刻意可变的：进度回调在 BLE 的
25	/// 高频路径上（每个 notify 页都来一次），不想每次都分配新对象。
26	class TransferTask {
27	  /// 创建任务；一般走 [TransferCenter.begin]，不要直接 new。
28	  TransferTask({
29	    required this.id,
30	    required this.title,
31	    this.kind = '',
32	    this.total = 0,
33	    this.cancellable = false,
34	    this.onCancel,
35	  });
36	
37	  /// 唯一 id。
38	  final String id;
39	
40	  /// 标题（调用方传入，已翻译）。
41	  final String title;
42	
43	  /// 任务类别，用于跨页面查「这类活儿是不是已经在跑」。
44	  ///
45	  /// 进度状态现在不属于任何页面了，页面重新进入时没法靠自己的
46	  /// `_busy` 判断重入 —— 得回来问 [TransferCenter]。
47	  final String kind;
48	
49	  /// 是否支持取消（决定悬浮框显不显示取消按钮）。
50	  final bool cancellable;
51	
52	  /// 点取消时回调；由发起方翻转自己的 stop 标志。
53	  final VoidCallback? onCancel;
54	
55	  /// 阶段 / 明细文案，例如「崩溃记录 2/5」。调用方给，已翻译。
56	  String phase = '';
57	
58	  /// 已完成量（单位由调用方定：字节或条目数）。
59	  int done = 0;
60	
61	  /// 总量；0 表示不确定进度（画成转圈而不是进度条）。
62	  int total = 0;
63	
64	  /// 累计已传字节，用于测速。
65	  int transferred = 0;
66	
67	  /// 滑动窗口测得的 KB/s。
68	  double kbs = 0;
69	
70	  /// 当前状态。
71	  TransferStatus status = TransferStatus.running;
72	
73	  /// 失败原因（status == failed 时有值）。
74	  String? error;
75	
76	  /// 开始时间。
77	  final DateTime startedAt = DateTime.now();
78	
79	  final Stopwatch _sw = Stopwatch()..start();
80	  int _lastBytes = 0;
81	  int _lastMs = 0;
82	
83	  /// 是否还在跑。
84	  bool get isRunning => status == TransferStatus.running;
85	
86	  /// 进度比例 0..1；[total] 为 0 时返回 null（不确定进度）。
87	  double? get fraction {
88	    if (total <= 0) return null;
89	    return (done / total).clamp(0.0, 1.0);
90	  }
91	
92	  /// 百分比整数。
93	  int get percent => ((fraction ?? 0) * 100).round();
94	
95	  /// 刷新测速窗口，返回是否有新的速度值。
96	  bool _tickSpeed(int nowBytes) {
97	    final ms = _sw.elapsedMilliseconds;
98	    final dt = ms - _lastMs;
99	    if (dt < 280) return false;
100	    final db = nowBytes - _lastBytes;
101	    if (db >= 0) {
102	      kbs = db * 1000 / (dt < 1 ? 1 : dt) / 1024;
103	    }
104	    _lastBytes = nowBytes;
105	    _lastMs = ms;
106	    return true;
107	  }
108	}
