110	/// 全 App 统一的抓取任务登记处：谁在抓、抓到哪了、多快。
111	///
112	/// 存在的理由是需求「页面退出不知道是不是还在抓取」——进度不能挂在
113	/// 某个页面的 `State` 上，否则退出页面就看不到了。这里只存状态，
114	/// 悬浮框 [TransferOverlay] 通过 `GetMaterialApp.builder` 挂在所有路由之外，
115	/// 所以切页、返回都不影响它。
116	///
117	/// 注意：这里**不**负责发请求，也不管串行化。Companion 的 BLE FS 通道
118	/// 本来就是串行的，并发发起会互相踩；调用方自己保证不重入
119	///（现有的 `_pulling` / `_busy` 标志继续保留）。
120	class TransferCenter extends GetxService {
121	  /// 取全局单例。已在 `main()` 里 `Get.put(..., permanent: true)`。
122	  static TransferCenter get to => Get.find<TransferCenter>();
123	
124	  /// 当前任务列表，新的在前。
125	  final tasks = <TransferTask>[].obs;
126	
127	  final _changes = StreamController<void>.broadcast();
128	
129	  /// 任务表变化流。
130	  ///
131	  /// 给「页面已经重建过、本地标志丢了」的场景用：`tasks` 是 `RxList`，
132	  /// 没法用 `ever<bool>` 订阅，而把整个 build 包进 `Obx` 又太贵。
133	  Stream<void> get changes => _changes.stream;
134	
135	  int _seq = 0;
136	
137	  /// 是否已有任务在跑（用于拦重入）。
138	  bool get isBusy => tasks.any((t) => t.isRunning);
139	
140	  /// 当前正在跑的任务条数。
141	  int get runningCount => tasks.where((t) => t.isRunning).length;
142	
143	  /// 正在跑的任务。
144	  List<TransferTask> get runningTasks =>
145	      [for (final t in tasks) if (t.isRunning) t];
146	
147	  /// 悬浮球该不该露头。
148	  ///
149	  /// 判据是**任务表里还有没有东西**，而不是"还在不在跑"—— 结束后的任务会
150	  /// 靠 [_scheduleDrop] 的延时留在表里一会儿，正是为了让用户看见结果。
151	  /// 早先这里只算 running/failed，于是「没东西要同步」那种几十毫秒就结束的
152	  /// 活儿，`finish()` 一落状态球就滑走了，压根来不及看，见 [_minVisible]。
153	  ///
154	  /// 任务失败后**故意**不设超时：静默把错误滑走，用户就永远不知道刚才那次
155	  /// 抓取挂了。失败的条目要等人点了关闭才消失。
156	  bool get hasWork => tasks.isNotEmpty;
157	
158	  /// 某一类任务是否正在跑。
159	  ///
160	  /// 页面被销毁重建后 `_busy` 之类的本地标志就没了，重入判断得回到这里来问。
161	  bool isKindRunning(String kind) =>
162	      tasks.any((t) => t.isRunning && t.kind == kind);
163	
164	  /// 取第一条第 [kind] 类且还在跑的任务。
165	  TransferTask? runningOfKind(String kind) {
166	    for (final t in tasks) {
167	      if (t.isRunning && t.kind == kind) return t;
168	    }
169	    return null;
170	  }
171	
172	  DateTime _lastNotify = DateTime.fromMillisecondsSinceEpoch(0);
173	
174	  /// 登记一条新任务。
175	  TransferTask begin({
176	    required String title,
177	    String kind = '',
178	    int total = 0,
179	    bool cancellable = false,
180	    VoidCallback? onCancel,
181	  }) {
182	    final t = TransferTask(
183	      id: 'T${DateTime.now().millisecondsSinceEpoch}_${_seq++}',
184	      title: title,
185	      kind: kind,
186	      total: total,
187	      cancellable: cancellable,
188	      onCancel: onCancel,
189	    );
190	    tasks.insert(0, t);
191	    _notify(force: true);
192	    return t;
193	  }
194	
195	  /// 上报进度。
196	  ///
197	  /// [done] / [total] 单位由调用方定；[transferred] 是累计**字节**，
198	  /// 只用来算速度（条目计数的流程可以不给）。
199	  /// [phase] 是阶段文案，变了就立刻刷新，避免"卡住"的错觉。
200	  void progress(
201	    TransferTask t, {
202	    int? done,
203	    int? total,
204	    int? transferred,
205	    String? phase,
206	  }) {
207	    if (!t.isRunning) return;
208	    final phaseChanged = phase != null && phase != t.phase;
209	    if (done != null) t.done = done;
210	    if (total != null) t.total = total;
211	    if (transferred != null) t.transferred = transferred;
212	    if (phase != null) t.phase = phase;
213	    t._tickSpeed(t.transferred);
214	    _notify(force: phaseChanged);
215	  }
216	
217	  /// 正常结束。默认成功后从悬浮框移除（失败/取消会留着让人看见）。
218	  ///
219	  /// [message] 是可选的结果文案，会覆盖卡片上的明细行。给「没东西要同步」
220	  /// 这类**什么也没做**的收尾用：光一个 ✓ 看不出为什么这么快就结束了。
221	  void finish(TransferTask t, {String? message}) {
222	    if (!t.isRunning) return;
223	    t.status = TransferStatus.done;
224	    t.kbs = 0;
225	    if (message != null && message.isNotEmpty) t.phase = message;
226	    if (t.total > 0) t.done = t.total;
227	    _notify(force: true);
228	    // 成功不留痕迹：悬浮框只在"还在抓"时有意义。
229	    _scheduleDrop(t);
230	  }
231	
232	  /// 出错结束，保留在悬浮框里直到用户点掉。
233	  void fail(TransferTask t, Object error) {
234	    if (!t.isRunning) return;
235	    t.status = TransferStatus.failed;
236	    t.kbs = 0;
237	    t.error = error.toString();
238	    _notify(force: true);
239	  }
240	
241	  /// 用户取消。
242	  void cancel(TransferTask t) {
243	    if (!t.isRunning) return;
244	    t.onCancel?.call();
245	    t.status = TransferStatus.cancelled;
246	    t.kbs = 0;
247	    _notify(force: true);
248	    _scheduleDrop(t);
249	  }
250	
251	  /// 从列表里手动移除（悬浮框上的关闭按钮）。
252	  void dismiss(TransferTask t) {
253	    tasks.removeWhere((e) => e.id == t.id);
254	    _notify(force: true);
255	  }
256	
257	  /// 清掉所有已结束的任务。
258	  void clearFinished() {
259	    tasks.removeWhere((t) => !t.isRunning);
260	    _notify(force: true);
261	  }
262	
263	  /// 任务从**登记那一刻**起，至少要在屏幕上待这么久。
264	  ///
265	  /// 「没东西要同步」这类活儿几十毫秒就跑完了。如果按「结束即开始收」，悬浮球
266	  /// 滑进来（280 ms）还没停稳就开始滑出去，用户只看见一道影子，更别说看清跑的是
267	  /// 哪一条、结果是成功还是没内容。所以可见时长从 [TransferTask.startedAt] 起算，
268	  /// 不足的补足。
269	  static const _minVisible = Duration(milliseconds: 2600);
270	
271	  /// 正常结束（成功 / 取消）后再多停留一会儿，让 ✓ 和结果文案能被读到。
272	  ///
273	  /// 失败的条目不走这里 —— 它们一直留着，等人点关闭。
274	  static const _doneHold = Duration(milliseconds: 1800);
275	
276	  void _scheduleDrop(TransferTask t) {
277	    // 已经显示够久了就只加 [_doneHold]；刚开始就结束的补到 [_minVisible]。
278	    final elapsed = DateTime.now().difference(t.startedAt);
279	    final toMinVisible = _minVisible - elapsed;
280	    final wait = toMinVisible > _doneHold ? toMinVisible : _doneHold;
281	    Timer(wait, () {
282	      if (t.isRunning) return;
283	      tasks.removeWhere((e) => e.id == t.id);
284	      _notify(force: true);
285	    });
286	  }
287	
288	  /// 节流刷新：BLE 进度回调很密，没必要每帧都重建悬浮框。
289	  void _notify({bool force = false}) {
290	    final now = DateTime.now();
291	    if (!force &&
292	        now.difference(_lastNotify) < const Duration(milliseconds: 80)) {
293	      return;
294	    }
295	    _lastNotify = now;
296	    tasks.refresh();
297	    if (!_changes.isClosed) _changes.add(null);
298	  }
299	}
