95	  void _onXferProgress(String label, int done, int total) {
96	    _xferDone = done;
97	    _xferTotal = total;
98	    _xferT0 ??= DateTime.now();
99	    final now = DateTime.now();
100	    final elapsed = now.difference(_xferT0!).inMilliseconds.clamp(1, 1 << 30);
101	    final kbs = done * 1000 / elapsed / 1024;
102	    if (done == total || elapsed - _xferLogMs >= 250) {
103	      _xferLogMs = elapsed;
104	      AppLog.i(
105	        'CompanionFs',
106	        '$label ${kbs.toStringAsFixed(1)} KB/s  $done/$total',
107	      );
108	    }
109	    // 全局悬浮框：本页自己的 kbs 是「从开始到现在的均值」，中心的
110	    // 是滑动窗口，更贴近当前速度，所以两边各留各的。
111	    final task = _task;
112	    if (task != null) {
113	      TransferCenter.to.progress(
114	        task,
115	        done: done,
116	        total: total,
117	        transferred: done,
118	        phase: label,
119	      );
120	    }
121	    if (done < total &&
122	        _xferPaintAt != null &&
123	        now.difference(_xferPaintAt!) < const Duration(milliseconds: 120)) {
124	      return;
125	    }
126	    _xferPaintAt = now;
127	    if (!mounted) return;
128	    setState(() => _status = _progressText(label, done, total, kbs));
129	  }
130	
131	  String _progressText(String label, int done, int total, [double? kbs]) {
132	    if (total <= 0) return label;
133	    final pct = ((done / total) * 100).clamp(0, 100).toStringAsFixed(0);
134	    final speed = kbs == null ? '' : ' ${kbs.toStringAsFixed(1)} KB/s';
135	    return '$label ${formatBytes(done)} / ${formatBytes(total)}（$pct%）$speed';
136	  }
