613	  /// Android SAF 常把任意文件的 [XFile.name] 报成 `.bin`，这里只找回原名/原扩展名。
614	  static const _placeholderExt = {'.bin', '.dat', '.tmp', '.file', '.download'};
615	
616	  bool _isPlaceholderName(String name) {
617	    final ext = p.extension(name).toLowerCase();
618	    final stem = p.basenameWithoutExtension(name).toLowerCase();
619	    return ext.isEmpty ||
620	        _placeholderExt.contains(ext) ||
621	        stem.isEmpty ||
622	        stem == 'document' ||
623	        stem == 'content' ||
624	        stem == 'file' ||
625	        stem == 'octet-stream';
626	  }
627	
628	  String? _extFromMime(String? mime) {
629	    final m = (mime ?? '').toLowerCase();
630	    if (m.isEmpty) return null;
631	    if (m.contains('gpx')) return '.gpx';
632	    if (m.contains('kml')) return '.kml';
633	    if (m.contains('json')) return '.json';
634	    if (m.contains('fit')) return '.fit';
635	    if (m == 'text/xml' || m == 'application/xml') return '.xml';
636	    if (m.startsWith('text/')) return '.txt';
637	    return null;
638	  }
639	
640	  String? _extFromPath(String path) {
641	    if (path.isEmpty) return null;
642	    var raw = path;
643	    try {
644	      raw = Uri.decodeFull(raw);
645	    } catch (_) {}
646	    final seg = raw.split('/').last.split('?').first;
647	    final ext = p.extension(seg).toLowerCase();
648	    if (ext.isEmpty || _placeholderExt.contains(ext)) return null;
649	    return ext;
650	  }
651	
652	  bool _looksLikeGpx(Uint8List bytes) {
653	    if (bytes.length < 8) return false;
654	    var start = 0;
655	    final limit = bytes.length < 8192 ? bytes.length : 8192;
656	    if (limit >= 3 && bytes[0] == 0xef && bytes[1] == 0xbb && bytes[2] == 0xbf) {
657	      start = 3;
658	    }
659	    String head;
660	    if (limit >= 2 && bytes[0] == 0xff && bytes[1] == 0xfe) {
661	      final chars = <int>[];
662	      for (var i = 2; i + 1 < limit; i += 2) {
663	        final c = bytes[i];
664	        if (c != 0) chars.add(c);
665	      }
666	      head = String.fromCharCodes(chars);
667	    } else {
668	      head = String.fromCharCodes(bytes.sublist(start, limit));
669	    }
670	    final h = head.toLowerCase();
671	    return h.contains('<gpx') ||
672	        h.contains('topografix.com/gpx') ||
673	        h.contains('<trkpt');
674	  }
675	
676	  String _uploadName(XFile file, Uint8List bytes) {
677	    final fromName = file.name.trim().isEmpty ? '' : p.basename(file.name);
678	    final fromPath = file.path.isEmpty ? '' : p.basename(file.path);
679	
680	    var name = fromName.isNotEmpty ? fromName : fromPath;
681	    if (fromPath.isNotEmpty &&
682	        _isPlaceholderName(name) &&
683	        !_isPlaceholderName(fromPath)) {
684	      name = fromPath;
685	    }
686	    if (name.isEmpty) name = 'upload';
687	
688	    if (_isPlaceholderName(name)) {
689	      // SAF 常把显示名改成 .bin；优先从真实路径/MIME/内容找回原来的类型。
690	      final recovered = _extFromPath(file.path) ??
691	          _extFromMime(file.mimeType) ??
692	          (_looksLikeGpx(bytes) ? '.gpx' : null);
693	      if (recovered != null) {
694	        var stem = p.basenameWithoutExtension(name);
695	        if (stem.isEmpty ||
696	            stem.toLowerCase() == 'document' ||
697	            stem.toLowerCase() == 'content' ||
698	            stem.toLowerCase() == 'file' ||
699	            stem.toLowerCase() == 'octet-stream') {
700	          final pathStem = p.basenameWithoutExtension(fromPath);
701	          stem = pathStem.isNotEmpty ? pathStem : 'upload';
702	        }
703	        name = '$stem$recovered';
704	      }
705	    }
706	
707	    AppLog.i(
708	      'CompanionFs',
709	      '上传原名 name=${file.name} path=${file.path} mime=${file.mimeType} -> $name',
710	    );
711	    return name;
712	  }
